#!/usr/bin/env python3
"""Second, disjoint arithmetic path for the rho column: Python's C-level math.log2 on
exact big integers (no mpmath), plus the pi constant from math. Reads r from the JSON
output of rho_column.py only for the integer values (which were parsed from the frozen
FIPS text); the log arithmetic shares no code with the mpmath path."""
import json, math
d = json.load(open("rho_column.out.json"))["rho_rows"]
claimed = {"K-571": 279.7471, "B-571": 284.8257, "K-283": 136.2534, "B-283": 140.8257}
out = {}
for c, row in d.items():
    r = int(row["r_decimal"]); k = row["k_established"]
    v = 0.5 * (math.log2(math.pi) + math.log2(r) - 2.0 - math.log2(k))
    out[c] = {"float64_rho": v, "mpmath_rho": row["log2_matched_rho"],
              "float_minus_mpmath": v - float(row["log2_matched_rho"]),
              "abs_diff_vs_claimed": abs(v - claimed[c]), "within_0.01": abs(v - claimed[c]) <= 0.01}
ell = 680564733841876926932320129493409985129
v130 = 0.5 * (math.log2(math.pi) + math.log2(ell) - 2.0 - math.log2(131)) + math.log2(1.069993)
out["ECC2K-130_with_walk"] = {"float64": v130, "diff_vs_60.9": abs(v130 - 60.9)}
print(json.dumps(out, indent=1))
